#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#
# shellcheck disable=SC1087,SC2317
#   SC1087: the library's "$e[Enter keeps current]" suffix is literal text after a
#     variable expansion, not an array subscript — a false positive, and the
#     library is shared verbatim across wizards so it is not rewritten here.
#   SC2317: the library carries helpers (set_secret/set_var, for gh) that this
#     particular wizard never calls; they are reachable for other wizards.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Cleanup for this wizard's temp files + the backgrounded `tailscale up`.
# (Library tmpfiles inside write_env are created and removed within the
# function; these live across stages, so they get the trap.)
LOG=""; FOUT=""; TS_PID=""; RENDER_OUT=""; RENDER_ERR=""; _cb_tmp=""
wizard_cleanup() {
  rm -f "$LOG" "$FOUT" "$RENDER_OUT" "$RENDER_ERR" "$_cb_tmp" 2>/dev/null || true
  if [[ -n "$TS_PID" ]] && kill -0 "$TS_PID" 2>/dev/null; then
    kill "$TS_PID" 2>/dev/null || true
  fi
}
trap wizard_cleanup EXIT INT TERM

# _valid_tsdns HOST: strict tailnet-hostname check for preset paths —
# every dot-separated label must satisfy the TS_HOST shape (lowercase,
# label-bound), and at least two labels must precede .ts.net (real
# tailnet DNS is always <host>.<tailnet> — a truncated paste like
# a.ts.net must fail here, not at the probe).
_valid_tsdns() {
  local rest="$1" label
  [[ "$rest" == *.ts.net ]] || return 1
  rest="${rest%.ts.net}"
  [[ "$rest" == *.* ]] || return 1
  while [[ "$rest" == *.* ]]; do
    label="${rest%%.*}"
    [[ "$label" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]] || return 1
    rest="${rest#*.}"
  done
  [[ "$rest" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]]
}

REPO_DIR="${REPO_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
# ${ENV_FILE:-...} keeps the library contract: callers (and dry-run renders
# against a throwaway copy) can point it elsewhere.
ENV_FILE="${ENV_FILE:-$REPO_DIR/.env}"
# The library already defaulted ENV_FILE to the relative ".env" at load, so
# the :- above never fires on a normal run — normalize that exact default to
# the repo root, or running from /tmp reads /tmp/.env and stage 8 exits.
if [[ "$ENV_FILE" == ".env" ]]; then ENV_FILE="$REPO_DIR/.env"; fi
# An explicit relative export (ENV_FILE=throwaway.env) would otherwise
# split-brain: stage 8 writes against the caller's cwd while the render
# cd's to REPO_DIR first. Canonicalize once, against the invoking cwd.
if [[ "$ENV_FILE" != /* ]]; then ENV_FILE="$PWD/$ENV_FILE"; fi
TS_HOST="${TS_HOST:-}"  # defaulted to hostname -s in stage 3, after the hostname preflight below
TS_DNS="${TS_DNS:-}"          # <name>.<tailnet>.ts.net, no trailing dot
REDIRECT_URI="${REDIRECT_URI:-}"  # preset honoured; empty means derive from TS_DNS below
_redirect_preset="${REDIRECT_URI:-}"

banner "Google connectors over Tailscale Funnel"

# ── Stage 1: preflight ────────────────────────────────────────────────────
stage "Preflight: what this will change"
say "This sets up the OAuth callback for the Gmail/Calendar connectors."
say "Plan: Tailscale Funnel terminates public TLS on 443 and forwards to the"
say "      existing nginx proxy on localhost:8080. No ports are opened, no"
say "      domain is bought. The app keeps its current Server URL."
say "      Note: the funnel publishes the whole proxy (chat + sync stay"
say "      PASSWORD-gated); the OAuth callback is the only new unauthenticated"
say "      surface. Do not share the *.ts.net URL."
printf '\n'
say "What is on disk right now:"
for k in GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REDIRECT_URL CONNECTORS_ENCRYPTION_KEY; do
  if v=$(_existing "$k" 2>/dev/null) && [[ -n "$v" ]]; then note "  $k: set"
  else note "  $k: MISSING"; fi
done
say "  tailscale: $(command -v tailscale >/dev/null 2>&1 && echo installed || echo 'not installed')"
if curl -fsS --max-time 5 http://127.0.0.1:8080/ping >/dev/null 2>&1; then
  note "  proxy :8080: listening"
else
  note "  proxy :8080: NOT answering (/ping)"
fi
# Dependency preflight: every external the stages shell out to. jq is the
# critical one — without it every tailscale-status check misreads as down.
# (tailscale itself is installed in stage 2, so its absence here is expected.)
_missing=""
for _dep in jq openssl curl podman podman-compose seq hostname; do
  if ! command -v "$_dep" >/dev/null 2>&1; then _missing="${_missing:+$_missing }$_dep"; fi
done
unset _dep
if [[ -n "$_missing" ]]; then
  warn "missing:${_missing} — install them, then re-run"
  exit 1
fi
unset _missing
if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
  warn "not running as root: tailscale install/up/funnel typically need root"
  warn "(upstream examples use 'sudo tailscale ...'). Re-run with sudo if"
  warn "those steps fail."
  if ! confirm "Continue as non-root?"; then
    say "Stopped. Nothing changed."
    exit 1
  fi
fi
printf '\n'
note "This host is the live stack. Writing .env is safe (inert until the"
note "pi container is recreated — ./scripts/hermes.sh restart recreates it;"
note "a plain container restart without recreation will not pick up .env)."
note "Nothing is restarted by this wizard."
note "Dry-run knobs (all optional): TS_DNS presets skip discovery and the"
note "probe wait, REDIRECT_URI presets skip derivation, ENV_FILE points at"
note "another file, SKIP_PROBE=1 skips the wait."
printf '\n'
if ! confirm "Proceed with Tailscale Funnel setup on this host?"; then
  say "Stopped. Nothing changed."
  exit 1
fi

# ── Stage 2: install ──────────────────────────────────────────────────────
stage "Install Tailscale"
if command -v tailscale >/dev/null 2>&1; then
  note "already installed: $(tailscale version 2>/dev/null | head -n1 || true)"
else
  _codename=""; [[ -f /etc/os-release ]] && _codename=$(sed -n 's/^VERSION_CODENAME=//p' /etc/os-release | tr -d '"')
  say "Installing from Tailscale's official apt repo${_codename:+ (Ubuntu $_codename)}."
  unset _codename
  note "This adds /etc/apt/sources.list.d/tailscale.list and the tailscaled service."
  printf '\n'
  # The stage-1 EUID gate lets non-root continue; the install itself cannot
  # succeed without root, so stop here instead of burning a doomed download.
  if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
    warn "cannot install as non-root — re-run with sudo, then re-run this wizard"
    exit 1
  fi
  if ! confirm "Install Tailscale now?"; then
    warn "skipped install; re-run this wizard when ready"
    exit 1
  fi
  # Intentionally the upstream installer (no pinning): Tailscale's documented
  # install path; the repo otherwise avoids pipe-to-shell for its own code.
  curl -fsSL https://tailscale.com/install.sh | sh || {
    warn "Tailscale download/install failed (network?). Re-run the wizard when it works."
    exit 1
  }
  printf '\n'
  printf '  %s✓%s installed %s\n' "$GREEN" "$RESET" "$(tailscale version 2>/dev/null | head -n1 || true)"
fi
if command -v systemctl >/dev/null 2>&1; then
  say "Service: $(systemctl is-active tailscaled 2>/dev/null || true)"
else
  note "systemctl absent (non-systemd host); tailscaled state unchecked"
fi

# ── Stage 3: join the tailnet ─────────────────────────────────────────────
stage "Join your tailnet"
if tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
  note "already connected"
  TS_HOST=$(tailscale status --json | jq -r '.Self.HostName // empty' || true)
else
  say "The machine name becomes the public hostname: <name>.<tailnet>.ts.net"
  step "Pick a short lowercase name (letters, digits, hyphen)."
  # ask's Enter-keeps-current reads ENV_FILE, where TS_HOST never lives —
  # so remember an env preset explicitly instead of losing it to hostname -s.
  _ts_preset="${TS_HOST:-}"
  # Computed once: hostname -s can emit a dotted FQDN on minimal images —
  # cut to the first label so the strict regex below doesn't loop-reject
  # the default.
  _host_default=$(hostname -s | cut -d. -f1 || true)
  # An unset hostname yields an empty default, an empty fallback, and a
  # regex that rejects empty — an endless warn loop with no way forward
  # except Ctrl-C. Fail fast instead.
  if [[ -z "$_ts_preset" && -z "$_host_default" ]]; then
    warn "hostname is empty and no TS_HOST preset — set the hostname or export TS_HOST, then re-run"
    exit 1
  fi
  while true; do
    ask TS_HOST "Machine name [${TS_HOST:-$_host_default}]:" || { warn "no input — the wizard needs a terminal; re-run to try again"; exit 1; }
    TS_HOST="${TS_HOST:-${_ts_preset:-$_host_default}}"
    if [[ "$TS_HOST" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]]; then break; fi
    warn "invalid: use lowercase letters, digits, hyphens (no leading/trailing hyphen)"
    TS_HOST=""; _ts_preset=""
  done
  unset _ts_preset _host_default
  printf '\n'
  say "Opening a login URL. Sign in with your Tailscale account (creating one"
  say "on the free Personal plan is fine) and approve this machine."
  printf '\n'

  LOG=$(mktemp)
  tailscale up --hostname="$TS_HOST" </dev/null >"$LOG" 2>&1 &
  TS_PID=$!
  URL=""
  for __i in $(seq 1 60); do
    URL=$(grep -oE 'https://login\.tailscale\.com/[^[:space:]]+' "$LOG" | head -n1 || true)
    [[ -n "$URL" ]] && break
    kill -0 "$TS_PID" 2>/dev/null || break
    printf '%s' '.'; sleep 1
  done
  printf '\n'
  if [[ -n "$URL" ]]; then
    open_url "$URL"
    pause "Press Enter once you've approved the machine in the browser."
  else
    warn "no login URL appeared; output so far:"
    sed 's/^/      /' "$LOG" || true
    pause "Fix the above, then press Enter to check again."
  fi
  # If the setup process already exited (bad hostname, no root, daemon down),
  # the wait below can never succeed — check state once and fall through to
  # the "not Running yet" exit instead of two minutes of dots.
  _up_alive=0
  if kill -0 "$TS_PID" 2>/dev/null; then _up_alive=1; fi
  if (( _up_alive == 0 )) && ! tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
    note "setup process already exited and daemon not Running — skipping the wait"
  else
    for __i in $(seq 1 60); do
      tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1 && break
      printf '%s' '.'; sleep 2
    done
    printf '\n'
  fi
  unset _up_alive
  # `tailscale up` exits once the node is up, so by the time Running is
  # confirmed it is already reaped-or-reapable: wait so the EXIT trap can
  # never fire on a recycled PID. (Already-connected takes this path with
  # TS_PID empty — wait on "" is suppressed, hence the guard.)
  if [[ -n "$TS_PID" ]] && tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
    wait "$TS_PID" 2>/dev/null || true
    TS_PID=""
  fi
  # Clear the log path alongside the file itself so the trap goes quiet.
  rm -f "$LOG"; LOG=""
fi

if ! tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
  warn "tailscaled is not Running yet. Re-run the wizard when it is."
  tailscale status || true
  exit 1
fi

# TS_DNS honours a caller preset (dry-runs) instead of silently discarding
# it — same contract as ENV_FILE. Empty means discover from the daemon.
_DNS_FROM_PRESET=0
_URI_FROM_PRESET=0
if [[ -n "$TS_DNS" ]]; then
  # Presets are trusted for dry-runs but not for sed: validate the shape
  # before it reaches the stage-8 hostname refresh (|/&/newline injection).
  # Same strictness as TS_HOST, label by label (a typo like -foo..ts.net
  # must fail here, not at the probe in stage 4).
  if ! _valid_tsdns "$TS_DNS"; then
    warn "preset TS_DNS=$TS_DNS is not a <name>.<tailnet>.ts.net hostname; unset it to discover from the daemon"
    exit 1
  fi
  note "using preset TS_DNS=$TS_DNS (skipping discovery)"
  _DNS_FROM_PRESET=1
else
  TS_DNS=$(tailscale status --json 2>/dev/null | jq -r '.Self.DNSName // empty' | sed 's/\.$//' || true)
fi
# (no "null" check: jq -r ... // empty never emits the literal string.)
if [[ -z "$TS_DNS" ]]; then
  warn "could not read the tailnet DNS name (is MagicDNS enabled?)"
  exit 1
fi
printf '\n'
printf '  %s✓%s %s\n' "$GREEN" "$RESET" "https://$TS_DNS"

# ── Stage 4: funnel + public verification ─────────────────────────────────
stage "Publish the callback over HTTPS"
say "Funnel will terminate TLS with a publicly-trusted certificate and forward"
say "to the existing proxy on localhost:8080. Only ports 443/8443/10000 are"
say "allowed, so 443 it is."
printf '\n'
note "First run may prompt you to enable HTTPS certificates / MagicDNS for the"
note "tailnet, plus the 'funnel' node attribute in the tailnet policy file."
note "If it complains, enable them and re-run this stage:"
note "  DNS:     https://console.tailscale.com/admin/dns"
note "  Funnel attribute (Access controls → Add Funnel to policy):"
note "  https://console.tailscale.com/admin/acls"
printf '\n'

FOUT=$(mktemp)
# Re-runs are safe: if 443 already forwards to this proxy, keep it instead
# of erroring out of the wizard.
_funnel_status=$(tailscale funnel status 2>/dev/null || true)
# Real `funnel status` prints the public URL and the target on separate
# lines (https://<host>… on one, "|-- / proxy http://127.0.0.1:8080" on
# another — port 443 is implied by https://, never printed next to 8080),
# so match across the whole output: our target port plus a public-https
# marker. A short note on why not one ordered grep: that form never fires
# on real output and silently disables this fast path.
if echo "$_funnel_status" | grep -q "8080" && echo "$_funnel_status" | grep -qiE "https://|443"; then
  note "funnel already serving 443 → this proxy; keeping it"
  printf '%s\n' "$_funnel_status" | sed 's/^/      /' || true
  rm -f "$FOUT"; FOUT=""
fi
unset _funnel_status
if [[ -n "$FOUT" ]]; then
if ! tailscale funnel --bg --https=443 http://127.0.0.1:8080 >"$FOUT" 2>&1; then
  if grep -qiE "already|in use|exists" "$FOUT"; then
    note "funnel reports it is already serving; keeping the existing one"
  else
    warn "funnel did not start:"
    sed 's/^/      /' "$FOUT" || true
    pause "Fix the above (usually MagicDNS/HTTPS in the admin console), then press Enter to retry."
    tailscale funnel --bg --https=443 http://127.0.0.1:8080 >"$FOUT" 2>&1 || {
      if grep -qiE "already|in use|exists" "$FOUT"; then
        note "funnel reports it is already serving; keeping the existing one"
      else
        warn "still failing:"; sed 's/^/      /' "$FOUT" || true; exit 1
      fi
    }
  fi
fi
sed 's/^/      /' "$FOUT" || true
rm -f "$FOUT"; FOUT=""
fi
printf '\n'

if [[ -n "$_redirect_preset" ]]; then
  # Same treatment as the TS_DNS preset: write_env single-quote-escapes but
  # does not stop newlines, so a multiline preset would write a second line
  # into .env. read-based input can't contain one — only presets can.
  # Host part validated label by label, like TS_DNS above.
  _uri_host=""
  if [[ "$_redirect_preset" == https://*/p/api/connectors/callback ]]; then
    _uri_host="${_redirect_preset#https://}"
    _uri_host="${_uri_host%/p/api/connectors/callback}"
  fi
  if [[ -z "$_uri_host" ]] || ! _valid_tsdns "$_uri_host"; then
    warn "preset REDIRECT_URI is not an https://<name>.<tailnet>.ts.net/p/api/connectors/callback URL; unset it to derive from TS_DNS"
    exit 1
  fi
  unset _uri_host
  REDIRECT_URI="$_redirect_preset"
  _URI_FROM_PRESET=1
  note "using preset REDIRECT_URI (skipping derivation from TS_DNS)"
else
  REDIRECT_URI="https://$TS_DNS/p/api/connectors/callback"
  _URI_FROM_PRESET=0
fi
unset _redirect_preset
say "Waiting for public DNS + certificate (can take a few minutes)…"
# Preset/dry-run hostnames (or SKIP_PROBE=1) skip the 30× poll: a fake name
# would burn ~5 min of timeouts before the .env write. One opportunistic
# probe still reports status without the wait.
ok=0
issuer=""
if (( _DNS_FROM_PRESET )) || [[ "${SKIP_PROBE:-0}" == "1" ]]; then
  note "preset hostname — skipping the public-reachability wait"
  if curl -fsS --max-time 10 "https://$TS_DNS/p/healthz" >/dev/null 2>&1; then
    ok=1
  else
    note "not reachable from here right now (expected for a dry-run name)"
  fi
else
  for __i in $(seq 1 30); do
    if curl -fsS --max-time 10 "https://$TS_DNS/p/healthz" >/dev/null 2>&1; then ok=1; break; fi
    printf '%s' '.'; sleep 10
  done
fi
printf '\n'
if (( ok )); then
  printf '  %s✓%s public HTTPS reachable: https://%s/p/healthz\n' "$GREEN" "$RESET" "$TS_DNS"
  # curl just proved TCP; bound the TLS handshake too so a TLS stall can't
  # outlast the probe budget. timeout is coreutils-Linux-only (macOS ships
  # gtimeout at best), so use it when present and run bare otherwise —
  # same portability line as the tmp-file prune below.
  if command -v timeout >/dev/null 2>&1; then
    issuer=$(timeout 10 openssl s_client -connect "$TS_DNS:443" -servername "$TS_DNS" </dev/null 2>/dev/null \
             | openssl x509 -noout -issuer 2>/dev/null || true)
  else
    issuer=$(openssl s_client -connect "$TS_DNS:443" -servername "$TS_DNS" </dev/null 2>/dev/null \
             | openssl x509 -noout -issuer 2>/dev/null || true)
  fi
  if [[ -n "$issuer" ]]; then
    note "$issuer"
    note "Google accepts Let's Encrypt-issued certs."
  fi
elif (( _DNS_FROM_PRESET )) || [[ "${SKIP_PROBE:-0}" == "1" ]]; then
  # Preset/dry-run names were already reassured above — a fake name never
  # propagates, so the DNS-wait message below would misdirect those users.
  note "continuing to the .env write without public reachability"
else
  warn "not reachable yet (DNS can take up to 10 min to propagate)."
  warn "You can continue — the URI below is still correct; re-run the probe later if needed."
fi
printf '\n'
say "This is the exact string to register in Google (copy it verbatim):"
printf '\n  %s%s%s\n\n' "$BOLD" "$REDIRECT_URI" "$RESET"
note "Through the proxy, /p/ is stripped before pi sees it, so this lands on"
note "/api/connectors/callback — the one route that needs no bearer."
note "Do NOT register the bare https://$TS_DNS/api/... form: on this proxy that"
note "path goes to health-api, not to pi-gateway."
pause "Press Enter once you've copied it."

# ── Stage 5: GCP project + APIs ───────────────────────────────────────────
stage "Google Cloud: project + APIs"
# Everything from here on is browser-driven. confirm can't tell EOF from
# "no" (read || true, then a regex test) — and here "no" is the long
# create-project branch, so EOF-on-a-TTY would walk it instead of exiting
# like every other gate. ask fails loudly on EOF instead: same y/N line
# discipline on a terminal, friendly stop anywhere else.
ask _HAVE_PROJ "Have a Google Cloud project with the Gmail and Calendar APIs enabled? [y/N]:" || { warn "no input — the wizard needs a terminal; re-run to try again"; exit 1; }
_have_yes=0
if [[ "$_HAVE_PROJ" =~ ^[Yy] ]]; then _have_yes=1; fi
unset _HAVE_PROJ
if (( _have_yes == 0 )); then
  step "Create a project (any name, e.g. agento-connectors)."
  open_url "https://console.cloud.google.com/projectcreate"
  pause "Press Enter once the project exists and is selected in the top bar."
  step "Enable the Gmail API."
  open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
  pause "Press Enter once it says 'API enabled'."
  step "Enable the Google Calendar API."
  open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com"
  pause "Press Enter once it says 'API enabled'."
else
  note "skipped (already enabled)"
fi
unset _have_yes

# ── Stage 6: consent screen ───────────────────────────────────────────────
stage "Google Cloud: consent screen + scopes"
say "User type EXTERNAL, publishing status TESTING, yourself as a test user."
note "Testing is the only free option here: publishing needs Google"
note "verification (a paid CASA assessment) for these restricted scopes."
note "Cost of Testing: refresh tokens expire after 7 days, so Gmail/Calendar"
note "will ask you to reconnect about weekly. Expected, not a bug."
printf '\n'
open_url "https://console.cloud.google.com/auth/overview"
note "If that 404s, use APIs & Services → OAuth consent screen."
printf '\n'
step "Branding: app name, your support email, developer contact. Save."
step "Audience: External. (If it defaults to Internal, you need Workspace — pick External.)"
step "Data access → Add or remove scopes. Add exactly these three:"
printf '\n'
printf '      %s\n' "https://www.googleapis.com/auth/gmail.readonly"
printf '      %s\n' "https://www.googleapis.com/auth/gmail.compose"
printf '      %s\n' "https://www.googleapis.com/auth/calendar.readonly"
printf '\n'
note "Leave 'Google APIs' filter on 'Manually add' if the picker won't find them."
step "Audience → Test users → Add users → your own Gmail address."
printf '\n'
if ! confirm "Consent screen configured with those three scopes and yourself as a test user?"; then
  warn "re-run the wizard when it is; nothing below needs redoing"
  exit 1
fi

# ── Stage 7: OAuth client ─────────────────────────────────────────────────
stage "Google Cloud: OAuth client"
say "Create a Web application client whose redirect URI is exactly:"
printf '\n  %s%s%s\n\n' "$BOLD" "$REDIRECT_URI" "$RESET"
open_url "https://console.cloud.google.com/auth/clients"
note "Or: APIs & Services → Credentials → Create credentials → OAuth client ID."
printf '\n'
step "Application type: Web application."
step "Authorized redirect URIs → Add URI → paste the string above, then Create."
note "One URI only. A typo here surfaces later as redirect_uri_mismatch in the"
note "browser while every server-side check still passes."
printf '\n'
pause "Press Enter once the client is created and the dialog shows ID + secret."
# Retry loop like TS_HOST above: a wrong paste must not burn the console
# work that led here. EOF still exits (a wizard needs a terminal).
while true; do
  step "Copy the Client ID (…apps.googleusercontent.com)."
  ask GOOGLE_CLIENT_ID "Client ID:" || { warn "no input — the wizard needs a terminal; re-run to try again"; exit 1; }
  step "Copy the Client secret (starts GOCSPX-). It is shown once."
  ask_secret GOOGLE_CLIENT_SECRET "Client secret (hidden):" || { warn "no input — the wizard needs a terminal; re-run to try again"; exit 1; }
  # Console copy-paste trails whitespace; strip it before the shape checks so
  # a trailing space doesn't fail a good paste (tokens never contain any).
  GOOGLE_CLIENT_ID=$(printf '%s' "$GOOGLE_CLIENT_ID" | tr -d '[:space:]')
  GOOGLE_CLIENT_SECRET=$(printf '%s' "$GOOGLE_CLIENT_SECRET" | tr -d '[:space:]')
  _bad=""
  [[ "$GOOGLE_CLIENT_ID" != *".apps.googleusercontent.com" ]] && _bad="client id (want …apps.googleusercontent.com)"
  [[ "$GOOGLE_CLIENT_SECRET" != GOCSPX-* ]] && _bad="${_bad:+$_bad and }client secret (want GOCSPX-…)"
  if [[ -z "$_bad" ]]; then unset _bad; break; fi
  warn "doesn't look like what Google issues: $_bad — check the paste"
  unset _bad
  if ! confirm "Re-enter both values?"; then
    warn "stopping — re-run the wizard to try again (console work above is unaffected)"
    exit 1
  fi
done

# ── Stage 8: write .env + verify ──────────────────────────────────────────
stage "Write .env and verify"
if [[ ! -f "$ENV_FILE" ]]; then
  # Branch the hint: overrides resolve outside the repo root, so "at
  # $REPO_DIR" would send override users looking in the wrong place.
  if [[ "$ENV_FILE" == "$REPO_DIR/.env" ]]; then
    warn "no $ENV_FILE — fresh checkout? run ./scripts/hermes.sh init first (or cp .env.example .env)"
  else
    warn "no $ENV_FILE (ENV_FILE override) — create it first, then re-run"
  fi
  exit 1
fi
BACKUP="$ENV_FILE.bak.$(date +%Y%m%d%H%M%S).$$"
cp -p "$ENV_FILE" "$BACKUP"
note "backup: $BACKUP (if the run is interrupted mid-write, restore with: cp -p $BACKUP $ENV_FILE)"
# Secrets are about to land in this file: 0600 regardless of what the
# checkout/editor left behind (a fresh file already gets 0600 in write_env) —
# and the backup holds the same secrets, so it gets 0600 too.
chmod 600 "$ENV_FILE" "$BACKUP"
# Backups are full-secret copies — keep the 5 newest by mtime, prune the
# rest. Pure bash (-ot comparison): no ls parsing, no GNU-only flags.
# nullglob is restored afterwards — the wizard must not mutate shell
# options it didn't own (matters if this file is ever sourced).
_baks=(); _nullglob_off=0; shopt -q nullglob || _nullglob_off=1
shopt -s nullglob; _baks=("$ENV_FILE".bak.*)
if (( _nullglob_off )); then shopt -u nullglob; fi
_pruned=0
while (( ${#_baks[@]} > 5 )); do
  _oldest="${_baks[0]}"
  for _b in "${_baks[@]}"; do
    if [[ "$_b" -ot "$_oldest" ]]; then _oldest="$_b"; fi
  done
  rm -f -- "$_oldest"
  _kept=()
  for _b in "${_baks[@]}"; do
    [[ "$_b" != "$_oldest" ]] || continue
    _kept+=("$_b")
  done
  _baks=("${_kept[@]}"); _pruned=1
done
if (( _pruned )); then note "pruned .env backups to the last 5"; fi
unset _baks _b _oldest _kept _pruned _nullglob_off

if v=$(_existing CONNECTORS_ENCRYPTION_KEY 2>/dev/null) && [[ -n "$v" ]]; then
  note "keeping the existing envelope key (rotating it would invalidate every stored grant)"
  CONNECTORS_ENCRYPTION_KEY="$v"
else
  CONNECTORS_ENCRYPTION_KEY=$(openssl rand -hex 32)
  note "generated a new envelope key (AES-256-GCM, 32 bytes hex)"
fi

# A comment block once, refreshed on re-runs (the tailnet name can change);
# write_env only replaces key lines, so this survives re-runs either way.
# The recorded host follows the redirect URL: on the preset path that host
# can differ from the daemon-derived TS_DNS.
_comment_host="$TS_DNS"
if (( _URI_FROM_PRESET )); then
  _comment_host="${REDIRECT_URI#https://}"; _comment_host="${_comment_host%%/*}"
fi
if ! grep -q '^# ── Google connectors' "$ENV_FILE"; then
  {
    printf '\n'
    printf '# ── Google connectors (#316) — added by setup wizard ──\n'
    printf '# Callback is served over Tailscale Funnel: https://%s\n' "$_comment_host"
    printf '# all-four-or-nothing: any missing piece leaves OAuth unconfigured (connect → 501).\n'
  } >> "$ENV_FILE"
else
  # Refresh the recorded hostname; keys below are fresh but this line is not.
  # Same tmp-file + cat pattern as the library's write_env, so a symlinked
  # .env stays a symlink (plain sed -i would replace it with a regular file).
  _cb_tmp=$(mktemp)
  sed "s|^# Callback is served over Tailscale Funnel:.*|# Callback is served over Tailscale Funnel: https://$_comment_host|" "$ENV_FILE" > "$_cb_tmp"
  cat "$_cb_tmp" > "$ENV_FILE"
  rm -f "$_cb_tmp"; _cb_tmp=""
fi
unset _comment_host

write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
write_env GOOGLE_REDIRECT_URL "$REDIRECT_URI"
write_env CONNECTORS_ENCRYPTION_KEY "$CONNECTORS_ENCRYPTION_KEY"

printf '\n'
say "Rendering compose to prove all four interpolate (values not printed)…"
# Same sudo-fallback pattern as scripts/lib/common.sh's podman_compose():
# a host whose user podman socket is missing needs sudo for compose.
_compose=(podman-compose)
podman info &>/dev/null || _compose=(sudo podman-compose)
# mktemp (mode 600) rather than fixed /tmp names: the render contains all
# four secret values interpolated, and a kill -9 would leave fixed paths
# behind on world-readable /tmp. Registered in the EXIT trap above.
RENDER_OUT=$(mktemp); RENDER_ERR=$(mktemp)
if ( cd "$REPO_DIR" && "${_compose[@]}" --env-file "$ENV_FILE" -f docker/docker-compose.yml config ) >"$RENDER_OUT" 2>"$RENDER_ERR"; then
  # Empty vars render as KEY: '' — the quote alone must not satisfy the
  # check, or a missing var reads as "reaches the pi service".
  _render_missing=""
  for k in GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REDIRECT_URL CONNECTORS_ENCRYPTION_KEY; do
    if grep -qE "^[[:space:]]*(-[[:space:]]*)?${k}[:=][[:space:]]*[\"']?[^\"'[:space:]]" "$RENDER_OUT"; then
      printf '  %s✓%s %s present in rendered compose config\n' "$GREEN" "$RESET" "$k"
    else
      printf '  %s✗%s %s renders EMPTY — fix it before restarting\n' "$YELLOW" "$RESET" "$k"
      _render_missing="$_render_missing $k"
    fi
  done
  if [[ -n "$_render_missing" ]]; then
    warn "empty render for:${_render_missing} — an empty value is the misconfiguration this step exists to catch"
    exit 1
  fi
  unset _render_missing
else
  warn "compose render failed (the .env writes stand, but nothing is verified — fix compose and re-run):"
  sed 's/^/      /' "$RENDER_ERR" || true
  exit 1
fi
rm -f "$RENDER_OUT" "$RENDER_ERR"; RENDER_OUT=""; RENDER_ERR=""

finish

# ── Closing checklist (not a stage; nothing else is automated) ────────────
printf '%s  Next, in this order:%s\n' "$BOLD" "$RESET"
printf '  1. Nothing is restarted yet. These vars are inert until the pi\n'
printf '     container is recreated — ./scripts/hermes.sh restart recreates\n'
printf '     it (a plain container restart without recreation will not pick\n'
printf '     up .env changes).\n'
printf '  2. Compare the canonical string the gateway logs at boot:\n'
printf '       %s -f %s/docker/docker-compose.yml logs pi | grep "OAuth configured"\n' "${_compose[*]}" "$REPO_DIR"
printf '     with what is registered in Google. They must match byte-for-byte;\n'
printf '     the log prints the canonical form, so register THAT.\n'
printf '  3. In the app: Settings → Connectors → Connect Gmail. Expect the\n'
printf '     "app isn'"'"'t verified" warning (Testing mode) → Advanced → proceed.\n'
printf '\n'
printf '  Re-running this wizard is safe: it keeps existing values as defaults.\n'
printf '  Envelope key: BACKUP FIRST — rotating it invalidates every stored grant.\n\n'
}

run_wizard "$@"; exit
